sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
	var body = request.body.data;

    // Validate
    if (!body.event_id) {
        response.setStatus(400);
        return { message: "Invalid payload" };
    }
    var assetGR = new GlideRecord('x_1558402_smart_0_asset_table');
    assetGR.addQuery('serial_number', body.asset_serial);
    assetGR.query();

    if (!assetGR.next()) {
    response.setStatus(400);
    return {
        message: "Invalid asset_serial. Asset not found."
    };
}

    // Insert Event Log
    var gr = new GlideRecord('x_1558402_smart_0_external_event_id');
    gr.initialize();
	if (gr.next()) {
    // Already exists → skip
    return {
        message: "Duplicate event ignored",
    };
}

    gr.event_id = body.event_id;
    gr.payload = JSON.stringify(body);
    gr.status = 'Received';

    gr.asset_serial_number = body.asset_serial;
    gr.description = body.description;
    gr.severity = body.severity;
	gr.source_system = "REST_API";

    gr.addQuery('event_id', body.event_id);
    gr.query();




    var id = gr.insert();  

    var processor = new CaseProcessor();
    var result = processor.createCaseFromEvent(body);

    response.setBody({
        message: result
    });

    return {
        message: "Event created",
        sys_id: id,

    };


})(request, response);
